INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a6df8b09c3b4b3cf7bf74bf59707a0066ed104b5/content/books/zizhi-tongjian/vol-293/year-0957/part-06/sources/library/jiuwudaishi-117-december-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002777；EPUB电子本，纸本及异文待核", "id": "169b6bb5-1f5d-51ba-bc54-64fd7d63e2a8"}, {"title": "宋史·巻二百六十一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a6df8b09c3b4b3cf7bf74bf59707a0066ed104b5/content/books/zizhi-tongjian/vol-293/year-0957/part-06/sources/library/songshi-261-chenchengzhao/source.txt", "note": "《宋史》巻二百六十一，段落 songshi-9c6e46fee832-p058016；EPUB电子本，纸本及异文待核", "id": "6c55a51b-f75c-5134-8a7e-4cb780386c3d"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a6df8b09c3b4b3cf7bf74bf59707a0066ed104b5/content/books/zizhi-tongjian/vol-293/year-0957/part-06/sources/library/tongjian-293-957-year-end/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003485；电子底本待考，分段待核", "id": "5c393367-49c3-5dd4-8086-4aade9ff6c5a"}, {"title": "宋史·巻一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/876887409d392e3dbf7c3028c1ed5b981c9251c0/content/books/zizhi-tongjian/vol-293/year-0957/part-02/sources/library/songshi-1-shouchun-campaign-957/source.txt", "note": "《宋史》巻一，段落 songshi-9c6e46fee832-p000515；EPUB电子本，纸本及异文待核", "id": "0fc4415c-5fb1-50c0-97c6-0ba498fefa4f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘承钧", "aliases": ["劉承鈞", "刘钧", "劉鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "崔勋", "aliases": ["崔勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹大同节度使、侍中。957年十一月率兵会北汉，与李存瑰军南侵潞州，至城下后退还。生卒年未载。", "biography": null, "status": "draft", "id": "ba3e229b-ebee-5da2-8af5-ef60d4fe54ed"}, {"name": "李存瑰", "aliases": ["李瓌", "李瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李存瑰，供奉官、赴西川赐诏者。", "biography": null, "status": "draft", "id": "a91449a7-a285-52aa-9c4a-0bf81e533f51"}, {"name": "范再遇", "aliases": ["範再遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐泗州守将。957年十二月率城降周，获任宿州团练使。生卒年未载。", "biography": null, "status": "draft", "id": "e3bcd11f-c3b5-5c14-bb25-dbfa08938323"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "陈承昭", "aliases": ["陳承昭", "陈承诏", "陳承詔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "江表人，南唐保义军节度使、濠泗楚海都应援使。957年十二月淮上战败被赵匡胤俘获，后获释并授后周右监门上将军。《宋史》本纪字作陈承诏，与本传承昭关联为姓名异文。生卒年未载。", "biography": null, "status": "draft", "id": "3dd794d3-04b5-5124-821a-1ae9f5b2456e"}, {"name": "郭廷谓", "aliases": ["郭廷謂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭城人，南唐濠州都监。957年率水军溯淮欲烧浮桥，被赵匡赞伏兵击败。生卒年未载。", "biography": null, "status": "draft", "id": "19bb918a-ace7-5a46-9480-796bbc67a61a"}, {"name": "李延邹", "aliases": ["李延鄒"], "era": "五代十国", "birth_year": null, "death_year": 957, "description": "鄱阳人，南唐濠州录事参军。957年拒绝替郭廷谓写降表，即使受兵威胁也不从，被郭廷谓杀害。李璟随后以官职褒赏其子。", "biography": null, "status": "draft", "id": "9061572c-b2c7-5be6-bd91-2b53a1ee3e91"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李延邹子（姓名未载）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李延邹之子，姓名、年龄未载。父亲因拒写降表被杀后，李璟授其官职，官名未载。", "biography": null, "status": "draft", "id": "ebe82521-d1d0-55ff-b346-75cb4da9e356"}, {"name": "崔万迪", "aliases": ["崔萬迪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐雄武军使、知涟水县事。957年十二月乙丑以涟水归降后周。生卒年未载。", "biography": null, "status": "draft", "id": "e2e0db4f-9009-5217-a56e-f6450a7af840"}, {"name": "陈迁", "aliases": ["陳遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐濠州兵马都监。《旧五代史》记957年十二月濠州归降后，获任后周沂州团练使。生卒年未载。", "biography": null, "status": "draft", "id": "2abf0fc3-560b-5100-ac91-17020151401a"}, {"name": "武守琦", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周铁骑左厢都指挥使。957年十二月奉命率数百骑赴扬州，至高邮；随后奏报扬州被焚、民众被驱南渡情况。生卒年未载。", "biography": null, "status": "draft", "id": "04485344-b2c0-5d5e-a186-764b36adc509"}, {"name": "卢膺", "aliases": ["盧膺"], "era": "五代十国", "birth_year": null, "death_year": 957, "description": "南汉中书侍郎、同平章事。957年年末条记其去世，具体月日未载。生年未载。", "biography": null, "status": "draft", "id": "415ce87e-65b5-552e-b845-fdcc94c4970e"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙", "刘晟", "劉晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "陈处尧", "aliases": ["陳處堯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐兵部郎中。956年李璟派其携厚礼渡海向契丹求援，契丹没有出兵，并将他留住。他后来多次当面指责契丹君主而未受处罚，具体日期未载。", "biography": null, "status": "draft", "id": "1209f341-ea4a-5e9d-b4d8-6574a2cef125"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
