ginal": "957年泗州攻降期间的概述，具体每项日未载", "dynasty": "五代十国", "description": "柴荣到泗州城下后，命采薪军士不侵犯民田。《通鉴》称民众感悦、争献薪草粮食，克城后无军士擅自入城。军纪与民众反应是史书记载，不据此否定其他战事中的侵掠。", "phases": [], "location_name": "泗州及周边民田", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "38171d56-5115-5ccf-8eba-cbed48ef612c"}, {"title": "柴荣派骑兵侦察洞口舰队，南唐军退守清口", "start_year": 957, "end_year": 957, "time_original": "957年十二月戊午追击以前，具体侦察日未载", "dynasty": "五代十国", "description": "柴荣派骑兵侦察洞口舰队，南唐军退守清口。", "phases": [], "location_name": "洞口至清口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4d4d2129-4b5c-5d92-8f12-6ea591e30c7f"}, {"title": "周军从淮河南北岸与河中三路追击南唐军", "start_year": 957, "end_year": 957, "time_original": "957年十二月戊午早晨", "dynasty": "五代十国", "description": "周军从淮河南北岸与河中三路追击南唐军。", "phases": [], "location_name": "淮河南北岸及中流", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "53eaafd0-0363-5bf1-8f82-74909edc6462"}, {"title": "周军追及南唐军，边战边行至楚州西北获胜", "start_year": 957, "end_year": 957, "time_original": "《通鉴》957年十二月庚申追及，辛酉至楚州西北获胜", "dynasty": "五代十国", "description": "周军追及南唐军，边战边行至楚州西北获胜。", "phases": [], "location_name": "清口至楚州西北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9227cc28-3582-5bda-a900-994c2e43370d"}, {"title": "赵匡胤为前锋追六十里，俘陈承昭", "start_year": 957, "end_year": 957, "time_original": "957年十二月辛酉楚州西北获胜后", "dynasty": "五代十国", "description": "赵匡胤为前锋追六十里，俘陈承昭。", "phases": [], "location_name": "淮河下游、楚州附近", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史